    }
  ],
  "glossary": [
    {"term": "泰勒公式", "definition": "将函数在某点展开为多项式，用于近似计算和误差分析。"},
    {"term": "拉格朗日余项", "definition": "泰勒展开的余项形式，给出截断误差的上界估计。"},
    {"term": "高阶导数", "definition": "函数多次求导后的导数，用于泰勒展开的系数计算。"},
    {"term": "截断误差", "definition": "用多项式近似函数时，舍弃高阶项产生的误差。"},
    {"term": "展开式", "definition": "函数按泰勒公式写成的多项式形式。"},
    {"term": "等价无穷小", "definition": "极限计算中，两个无穷小量比值的极限为1，可互相替换。"}
  ],
